function RemoveAt(elements: list[option[int]], idx: int) -> (result: list[option[int]]) {
    ensure (((len(result) == (len(elements) - 1)) ∧
    (∀(i: int) ::
        ((0 <= i < idx) ==>
            (result[i] == elements[i])))) ∧
    (∀(i: int) ::
        ((idx <= i < len(result)) ==>
            (result[i] == elements[(i + 1)]))));
}
